files.r2v_blocks.tcl:
# save old top molecule index
set oldtop [molinfo top]

# region rinf of style block
# create new empty VMD molecule to store the graphics primitives
set gfxmol [mol new]
mol top $gfxmol
mol rename $gfxmol {LAMMPS region rinf}
# set color and material
graphics $gfxmol color red
graphics $gfxmol material Glossy
draw triangle {-5 0.25 0} {-5 0.25 2} {-5 4 0}
draw triangle {-5 4 0} {-5 4 2} {-5 0.25 2}
draw triangle {-5 0.25 0} {-5 0.25 2} {2.5 0.25 0}
draw triangle {2.5 0.25 0} {2.5 0.25 2} {-5 0.25 2}
# draw triangle {2.5 0.25 0} {2.5 0.25 2} {2.5 4 0}
# draw triangle {2.5 4 0} {2.5 4 2} {2.5 0.25 2}
# draw triangle {-5 0.25 0} {2.5 0.25 0} {2.5 4 0}
# draw triangle {-5 0.25 0} {-5 4 0} {2.5 4 0}
draw triangle {-5 0.25 2} {2.5 0.25 2} {2.5 4 2}
draw triangle {-5 0.25 2} {-5 4 2} {2.5 4 2}
draw triangle {-5 4 0} {-5 4 2} {2.5 4 2}
draw triangle {-5 4 0} {2.5 4 0} {2.5 4 2}

# region rmov of style block
# create new empty VMD molecule to store the graphics primitives
set gfxmol [mol new]
mol top $gfxmol
mol rename $gfxmol {LAMMPS region rmov}
# set color and material
graphics $gfxmol color red
graphics $gfxmol material Glossy
draw triangle {0.35 -0.5 -0.199} {0.35 -0.5 2.401} {0.35 0.8 -0.199}
draw triangle {0.35 0.8 -0.199} {0.35 0.8 2.401} {0.35 -0.5 2.401}
draw triangle {0.35 -0.5 -0.199} {0.35 -0.5 2.401} {1.95 -0.5 -0.199}
draw triangle {1.95 -0.5 -0.199} {1.95 -0.5 2.401} {0.35 -0.5 2.401}
draw triangle {1.95 -0.5 -0.199} {1.95 -0.5 2.401} {1.95 0.8 -0.199}
draw triangle {1.95 0.8 -0.199} {1.95 0.8 2.401} {1.95 -0.5 2.401}
draw triangle {0.35 -0.5 -0.199} {1.95 -0.5 -0.199} {1.95 0.8 -0.199}
draw triangle {0.35 -0.5 -0.199} {0.35 0.8 -0.199} {1.95 0.8 -0.199}
draw triangle {0.35 -0.5 2.401} {1.95 -0.5 2.401} {1.95 0.8 2.401}
draw triangle {0.35 -0.5 2.401} {0.35 0.8 2.401} {1.95 0.8 2.401}
draw triangle {0.35 0.8 -0.199} {0.35 0.8 2.401} {1.95 0.8 2.401}
draw triangle {0.35 0.8 -0.199} {1.95 0.8 -0.199} {1.95 0.8 2.401}
after idle {if {$oldtop >= 0} {mol top $oldtop}; display resetview}

files.r2v_prism.tcl:
# save old top molecule index
set oldtop [molinfo top]

# region rpr of style prism
# create new empty VMD molecule to store the graphics primitives
set gfxmol [mol new]
mol top $gfxmol
mol rename $gfxmol {LAMMPS region rpr}
# set color and material
graphics $gfxmol color silver
graphics $gfxmol material Transparent
draw triangle {0 0 -1} {2 0 -1} {2.5 1.5 -1}
draw triangle {0 0 -1} {0.5 1.5 -1} {2.5 1.5 -1}
draw triangle {0 0 -1} {2 0 -1} {2.25 0.1 1}
draw triangle {0 0 -1} {0.25 0.1 1} {2.25 0.1 1}
draw triangle {2 0 -1} {2.25 0.1 1} {2.5 1.5 -1}
draw triangle {2.75 1.6 1} {2.25 0.1 1} {2.5 1.5 -1}
# draw triangle {0 0 -1} {0.5 1.5 -1} {0.75 1.6 1}
# draw triangle {0 0 -1} {0.25 0.1 1} {0.75 1.6 1}
# draw triangle {0.25 0.1 1} {2.25 0.1 1} {2.75 1.6 1}
# draw triangle {0.25 0.1 1} {0.75 1.6 1} {2.75 1.6 1}
draw triangle {0.5 1.5 -1} {2.5 1.5 -1} {2.75 1.6 1}
draw triangle {0.5 1.5 -1} {0.75 1.6 1} {2.75 1.6 1}
after idle {if {$oldtop >= 0} {mol top $oldtop}; display resetview}
